#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    double diff = (*(double *)a - *(double *)b);
    if (diff < 0) return -1;
    if (diff > 0) return 1;
    return 0;
}

int main() {
    double t;
    int n;
    if (scanf("%lf", &t) != 1) return 0;
    if (scanf("%d", &n) != 1) return 0;

    double *x = (double *)malloc(n * sizeof(double));
    for (int i = 0; i < n; i++) {
        scanf("%lf", &x[i]);
    }

    qsort(x, n, sizeof(double), cmp);

    double min_viz = (x[0] + x[1]) / 2.0;

    for (int i = 1; i < n - 1; i++) {
        double viz = (x[i + 1] - x[i - 1]) / 2.0;
        if (viz < min_viz) {
            min_viz = viz;
        }
    }

    double last_viz = t - (x[n - 2] + x[n - 1]) / 2.0;
    if (last_viz < min_viz) {
        min_viz = last_viz;
    }

    printf("%.2f\n", min_viz);

    free(x);
    return 0;
}
